@CrossOrigin
@RestController
@RequestMapping("/PersonQuery")
public class PersonQueryRestController extends BaseSpringRestController {
	
	public PersonQueryRestController( PersonService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Person using a UUID
     * @param		UUID personId
     * @return		Person
     */    
    @GetMapping("/load")
    public Person load( @RequestParam(required=true) UUID personId ) {
    	Person entity = null;

    	try {  
    		entity = service.getPerson( new PersonFetchOneSummary( personId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Person using Id " + personId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Person business objects
     * @return		Set<Person>
     */
    @GetMapping("/")
    public List<Person> loadAll() {                
    	List<Person> personList = null;
        
    	try {
            // load the Person
            personList = service.getAllPerson();
            
            if ( personList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Persons" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Persons ", exc );
        	return null;
        }

        return personList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Person person = null;
    protected PersonService service = null;
    private static final Logger LOGGER = Logger.getLogger(PersonQueryRestController.class.getName());
    
}
